def generated_loss(batch, model_output, extra):
    adv_gap = ops.clamp(batch['advantage_gap'], -20.0, 20.0)
    margin = ops.relu(1.0 - adv_gap)
    scale = ops.exp(-adv_gap)
    diff = batch['log_prob_l'] - batch['log_prob_w']
    base_loss = margin * scale * diff
    weight = batch.get('weight', None)
    if weight is not None:
        base_loss = base_loss * weight
    return ops.sum(base_loss)
